def js(s):
    return s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


def replace_block_by_en(t, en_anchor, ar, en, fn=None):
    pos = t.index(en_anchor)
    start = t.rfind("    b(", 0, pos)
    end = t.index("    ),", pos) + len("    ),")
    if fn is None:
        block = f'    b(\n      "{js(ar)}",\n      "{js(en)}",\n    ),'
    else:
        block = (
            f'    b(\n      "{js(ar)}",\n'
            f'      "{js(en)}",\n'
            f'      null,\n'
            f'      "{js(fn)}",\n'
            f'    ),'
        )
    return t[:start] + block + t[end:]


